    /// `codex | agy | muse | claude | http | other`.
    pub engine: String,
    /// The vendor CLASS of the endpoint (`classes::reviewer_class`), else `other`.
    pub provider: String,
    /// Model label (safe) or `unknown`.
    pub model: String,
    /// Purpose label (safe) or `unknown`.
    pub purpose: String,
    /// `usable` or `failed:<class>`.
    pub outcome: String,
    pub wall_seconds: f64,
    pub tokens_in: i64,
    pub tokens_out: i64,
    pub findings: i64,
    pub structured: bool,
    pub format_retry: bool,
    pub panel_size: u32,
    /// (M11) How many federation peers contributed to this consultation's pack â€” a COUNT only,
    /// never a name, a path or a connection string. Nothing federated ever reaches the hub.
    pub peers_used: u32,
    pub os: String,
    pub runtime: String,
    /// A tag from a fixed vocabulary; `None` for now (DESIGN Â§8). Never free text.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub topic_tag: Option<String>,
    /// The coordinator's usefulness mark (`yes | partly | no`) once known; else absent.
    #[serde(skip_serializing_if = "Option::is_none")]
    pub useful: Option<String>,
    /// Verified finding count once findings settle; else absent.
